import type { ParsedGearItem } from './csvParser'
import type { WeightUnit } from '@/types/database'

export interface ParsedGearItemWithUnit extends ParsedGearItem {
  weight_display_unit?: WeightUnit
}

export interface LighterPackParseResult {
  success: boolean
  data: ParsedGearItemWithUnit[]
  errors: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

// Category emoji mappings from LighterPack
const CATEGORY_MAPPINGS: Record<string, string> = {
  '🥾': 'Footwear',
  '🥋': 'Clothing',
  '⚡️': 'Electronics',
  '🍽️': 'Cooking',
  '💤': 'Sleep System',
  '⛺': 'Shelter',
  '💧': 'Water',
  '🎒': 'Pack',
  '🧭': 'Navigation',
  '🏥': 'First Aid',
  '🧴': 'Toiletries',
  '🔧': 'Tools',
  '📚': 'Documents',
  '🍫': 'Food',
  '🎯': 'Other'
}

/**
 * Parse a LighterPack public list URL
 */
export async function parseLighterPackUrl(url: string): Promise<LighterPackParseResult> {
  const result: LighterPackParseResult = {
    success: false,
    data: [],
    errors: []
  }

  try {
    // Validate URL format
    if (!isValidLighterPackUrl(url)) {
      result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
      return result
    }

    // For now, we'll create a proxy approach since we can't directly fetch cross-origin
    // In a real implementation, this would either:
    // 1. Use a backend proxy to fetch the LighterPack page
    // 2. Use a CORS proxy service
    // 3. Have users paste the HTML content

    result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
    return result

  } catch (error) {
    result.errors.push(`Failed to parse LighterPack URL: ${error instanceof Error ? error.message : 'Unknown error'}`)
    return result
  }
}

/**
 * Parse LighterPack HTML content (for when we have the HTML)
 */
export function parseLighterPackHtml(html: string): LighterPackParseResult {
  const result: LighterPackParseResult = {
    success: true,
    data: [],
    errors: [],
    metadata: {}
  }

  try {
    // Create a DOM parser to work with the HTML
    const parser = new DOMParser()
    const doc = parser.parseFromString(html, 'text/html')

    // Extract list metadata - try multiple selectors for the list name
    let listName = 'LighterPack List'

    // First try the list name element
    const listNameElement = doc.querySelector('.lpListName, h1.lpListName')
    if (listNameElement?.textContent?.trim()) {
      listName = listNameElement.textContent.trim()
    } else {
      // Fallback to title element, but clean it up
      const titleElement = doc.querySelector('title')
      const titleText = titleElement?.textContent?.trim()
      if (titleText && !titleText.includes('LighterPack') && titleText !== 'LighterPack') {
        listName = titleText
      }
    }

    result.metadata!.listName = listName

    // Try to parse the chartData JSON first
    const chartData = extractChartData(html)
    if (chartData) {
      console.log('[DEBUG] Using chartData parsing method')
      result.data = parseChartData(chartData)
    }

    // Fallback to HTML parsing if chartData fails
    if (result.data.length === 0) {
      console.log('[DEBUG] Using HTML structure parsing method')
      result.data = parseHtmlStructure(doc)
    }

    // Calculate metadata
    result.metadata!.itemCount = result.data.length
    result.metadata!.totalWeight = result.data.reduce((sum, item) => sum + item.weight_grams * item.quantity, 0)

    if (result.data.length === 0) {
      result.success = false
      result.errors.push('No gear items found in the LighterPack page')
    }

  } catch (error) {
    result.success = false
    result.errors.push(`Failed to parse HTML: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }

  return result
}

/**
 * Validate LighterPack URL format
 */
function isValidLighterPackUrl(url: string): boolean {
  try {
    const urlObj = new URL(url)
    return urlObj.hostname === 'lighterpack.com' && urlObj.pathname.startsWith('/r/')
  } catch {
    return false
  }
}

/**
 * Extract chartData parameter from the HTML
 */
function extractChartData(html: string): any | null {
  try {
    // Look for chartData parameter in the HTML
    const chartDataMatch = html.match(/chartData["\s]*=["\s]*([^"]+)/)
    if (!chartDataMatch) return null

    // Decode the URL-encoded JSON string
    const encodedData = chartDataMatch[1]
    const decodedData = decodeURIComponent(encodedData)

    return JSON.parse(decodedData)
  } catch {
    return null
  }
}

/**
 * Parse the chartData JSON structure
 */
function parseChartData(chartData: any): ParsedGearItemWithUnit[] {
  const items: ParsedGearItemWithUnit[] = []

  try {
    // ChartData structure varies, but typically has categories with items
    if (chartData.children) {
      for (const category of chartData.children) {
        const categoryName = mapEmojiToCategory(category.name) || 'Other'

        if (category.children) {
          for (const item of category.children) {
            const gearItem = parseChartDataItem(item, categoryName)
            if (gearItem) {
              items.push(gearItem)
            }
          }
        }
      }
    }
  } catch (error) {
    // Fallback to empty array if parsing fails
    console.warn('Failed to parse chartData:', error)
  }

  return items
}

/**
 * Parse individual item from chartData
 */
function parseChartDataItem(item: any, category: string): ParsedGearItemWithUnit | null {
  try {
    const name = item.name?.trim()
    if (!name) return null

    // Chart data might have weight in different formats
    let weight_grams = parseFloat(item.weight) || 0
    console.log(`[DEBUG] chartData item: ${item.name}, raw weight: ${item.weight}, parsed: ${weight_grams}`)

    // Check if this looks like milligrams (very large numbers)
    if (weight_grams > 10000) {
      console.log(`[DEBUG] Looks like milligrams, converting: ${weight_grams}mg -> ${weight_grams / 1000}g`)
      weight_grams = weight_grams / 1000
    }

    if (weight_grams <= 0) return null

    // Try to detect unit from raw weight string if available
    let unit: WeightUnit = 'g'
    if (item.weightText) {
      const { unit: detectedUnit } = parseWeightFromText(item.weightText)
      unit = detectedUnit
    }

    return {
      name,
      weight_grams: Math.round(weight_grams),
      weight_display_unit: unit,
      category,
      quantity: parseInt(item.qty) || 1,
      worn: item.worn === true || item.worn === 'true',
      consumable: item.consumable === true || item.consumable === 'true',
      price: item.price ? parseFloat(item.price) : undefined,
      description: item.description?.trim() || undefined,
      notes: item.notes?.trim() || undefined,
      url: item.url?.trim() || undefined
    }
  } catch {
    return null
  }
}

/**
 * Fallback HTML structure parsing
 */
function parseHtmlStructure(doc: Document): ParsedGearItemWithUnit[] {
  const items: ParsedGearItemWithUnit[] = []

  try {
    // Parse LighterPack's actual HTML structure
    const categoryElements = doc.querySelectorAll('.lpCategory')

    for (const categoryEl of categoryElements) {
      // Get category name
      const categoryNameEl = categoryEl.querySelector('.lpCategoryName')
      const categoryName = categoryNameEl?.textContent?.trim() || 'Other'

      // Get all items in this category
      const itemElements = categoryEl.querySelectorAll('.lpItem')

      for (const itemEl of itemElements) {
        const item = parseHtmlItem(itemEl, categoryName)
        if (item) {
          items.push(item)
        }
      }
    }
  } catch (error) {
    console.warn('Failed to parse HTML structure:', error)
  }

  return items
}

/**
 * Parse individual HTML item element for gear data
 */
function parseHtmlItem(element: Element, category: string): ParsedGearItemWithUnit | null {
  try {
    // Extract name from lpName span
    const nameEl = element.querySelector('.lpName')
    const name = nameEl?.textContent?.trim()
    if (!name) return null

    // Extract description from lpDescription span
    const descriptionEl = element.querySelector('.lpDescription')
    const description = descriptionEl?.textContent?.trim()

    // Combine name and description if description exists
    const fullName = description ? `${name} - ${description}` : name

    // Extract weight from lpWeightCell - need to get value and unit separately
    const weightEl = element.querySelector('.lpWeight')
    const weightValue = weightEl?.textContent?.trim() || '0'

    // Get the unit from lpDisplay span within lpUnitSelect
    const unitEl = element.querySelector('.lpUnitSelect .lpDisplay')
    const unitText = unitEl?.textContent?.trim() || 'g'

    console.log(`[DEBUG] HTML item weight: value="${weightValue}", unit="${unitText}"`)

    // Combine value and unit for parsing
    const weightText = `${weightValue}${unitText}`
    const { grams, unit } = parseWeightFromText(weightText)

    // Extract quantity from lpQtyCell
    const qtyEl = element.querySelector('.lpQtyCell')
    const qtyText = qtyEl?.textContent?.trim() || '1'
    const quantity = parseInt(qtyText) || 1

    // Check for worn flag - try multiple approaches
    let isWorn = false
    let isConsumable = false

    try {
      // First try: look for active worn/consumable icons
      const wornIcon = element.querySelector('.lpWorn.lpActive') || element.querySelector('i.lpWorn.lpActive')
      const consumableIcon = element.querySelector('.lpConsumable.lpActive') || element.querySelector('i.lpConsumable.lpActive')

      isWorn = wornIcon !== null
      isConsumable = consumableIcon !== null

      // Fallback: check element classes (original logic)
      if (!isWorn && !isConsumable) {
        isWorn = element.classList.contains('lpShowWorn')
        isConsumable = element.classList.contains('lpShowConsumable')
      }
    } catch (error) {
      // Ultimate fallback: default to false
      console.warn('[DEBUG] Error parsing worn/consumable flags:', error)
      isWorn = false
      isConsumable = false
    }

    console.log(`[DEBUG] HTML item flags: ${fullName} - worn: ${isWorn}, consumable: ${isConsumable}`)

    // Extract price if present
    const priceEl = element.querySelector('.lpPriceCell')
    const priceText = priceEl?.textContent?.trim()
    let price: number | undefined
    if (priceText) {
      const priceMatch = priceText.match(/[\d.,]+/)
      if (priceMatch) {
        price = parseFloat(priceMatch[0].replace(',', ''))
      }
    }

    // Extract URL if present - look for link elements or URL text
    const linkEl = element.querySelector('a[href]')
    const url = linkEl?.getAttribute('href')?.trim() || undefined

    return {
      name: fullName,
      weight_grams: grams,
      weight_display_unit: unit,
      category: mapCategoryName(category),
      quantity,
      worn: isWorn,
      consumable: isConsumable,
      price,
      description: description || undefined,
      url
    }
  } catch {
    return null
  }
}

/**
 * Map LighterPack category names to BetterPack categories
 */
function mapCategoryName(lighterPackCategory: string): string {
  const normalized = lighterPackCategory.toLowerCase().trim()

  // Direct mappings for common LighterPack categories
  const mappings: Record<string, string> = {
    'shelter': 'Shelter',
    'sleep system': 'Sleep System',
    'sleep': 'Sleep System',
    'cooking': 'Cooking',
    'cook': 'Cooking',
    'water': 'Water',
    'hydration': 'Water',
    'clothing': 'Clothing',
    'clothes': 'Clothing',
    'worn clothing': 'Clothing',
    'electronics': 'Electronics',
    'first aid': 'First Aid',
    'medical': 'First Aid',
    'navigation': 'Navigation',
    'nav': 'Navigation',
    'other': 'Other',
    'misc': 'Other',
    'miscellaneous': 'Other'
  }

  // Check for direct match
  if (mappings[normalized]) {
    return mappings[normalized]
  }

  // Check for partial matches
  for (const [key, value] of Object.entries(mappings)) {
    if (normalized.includes(key)) {
      return value
    }
  }

  // Default to Other if no match found
  return 'Other'
}

/**
 * Map emoji categories to our category names
 */
function mapEmojiToCategory(emojiCategory: string): string | null {
  for (const [emoji, category] of Object.entries(CATEGORY_MAPPINGS)) {
    if (emojiCategory.includes(emoji)) {
      return category
    }
  }
  return null
}

/**
 * Parse weight from text (handles various formats) and returns both grams and unit
 */
function parseWeightFromText(text: string): { grams: number; unit: WeightUnit } {
  console.log(`[DEBUG] parseWeightFromText input: "${text}"`)
  const cleaned = text.toLowerCase().replace(/[^\d.,ozlbkg\s]/g, '').trim()
  console.log(`[DEBUG] cleaned: "${cleaned}"`)

  // First check for combined lb + oz format (e.g., "1 lb 5 oz")
  if (cleaned.includes('lb') && cleaned.includes('oz')) {
    const lbOzMatch = cleaned.match(/(\d+\.?\d*)\s*lb\s*(\d+\.?\d*)\s*oz/)
    if (lbOzMatch) {
      const lbs = parseFloat(lbOzMatch[1])
      const ozs = parseFloat(lbOzMatch[2])
      return {
        grams: Math.round((lbs * 453.592) + (ozs * 28.3495)),
        unit: 'oz' // Display in oz since it has oz precision
      }
    }
  }

  const numberMatch = cleaned.match(/([\d.,]+)/)
  if (!numberMatch) return { grams: 0, unit: 'g' }

  const value = parseFloat(numberMatch[1].replace(',', ''))
  console.log(`[DEBUG] parsed value: ${value}`)
  if (isNaN(value)) return { grams: 0, unit: 'g' }

  // Check unit and convert to grams
  if (cleaned.includes('oz') && !cleaned.includes('lb')) {
    const grams = Math.round(value * 28.3495)
    console.log(`[DEBUG] ${value} oz -> ${grams}g`)
    return { 
      grams, // Convert oz to grams
      unit: 'oz'
    }
  } else if (cleaned.includes('lb')) {
    const grams = Math.round(value * 453.592)
    console.log(`[DEBUG] ${value} lb -> ${grams}g`)
    return { 
      grams, // Convert lb to grams
      unit: 'lb'
    }
  } else if (cleaned.includes('kg')) {
    const grams = Math.round(value * 1000)
    console.log(`[DEBUG] ${value} kg -> ${grams}g`)
    return { 
      grams, // Convert kg to grams
      unit: 'kg'
    }
  } else if (cleaned.includes('g')) {
    console.log(`[DEBUG] ${value}g (no conversion)`)
    return { 
      grams: Math.round(value),
      unit: 'g'
    }
  }

  // Default to grams if no unit specified
  console.log(`[DEBUG] ${value} defaulting to grams`)
  return { 
    grams: Math.round(value),
    unit: 'g'
  }
}

/**
 * Create a manual input helper for LighterPack data
 * This provides instructions for users to manually copy data
 */
export function createLighterPackInstructions(): string {
  return `
