import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Info, ExternalLink } from 'lucide-react'
import { parseLighterPackHtml } from '@/utils/lighterpackParser'
import type { ParsedGearItem } from '@/utils/csvParser'

interface UrlImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[], metadata?: any) => void
}

export function UrlImport({ onImportData }: UrlImportProps) {
  const [url, setUrl] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)

  const handleUrlImport = async () => {
    if (!url.trim()) {
      onImportData([], ['Please enter a LighterPack URL'])
      return
    }

    // Validate URL format
    if (!url.includes('lighterpack.com/r/')) {
      onImportData([], ['Invalid URL. Please enter a valid LighterPack share URL (e.g., https://lighterpack.com/r/abc123)'])
      return
    }

    setIsProcessing(true)

    try {
      // Use CORS proxy to fetch the LighterPack page
      // Try multiple CORS proxies for better reliability
      const proxies = [
        `https://corsproxy.io/?${encodeURIComponent(url.trim())}`,
        `https://cors-anywhere.herokuapp.com/${url.trim()}`,
        `https://api.allorigins.win/get?url=${encodeURIComponent(url.trim())}`
      ]

      let html = null
      let lastError = null

      for (const proxyUrl of proxies) {
        try {
          console.log(`Trying proxy: ${proxyUrl}`)
          const response = await fetch(proxyUrl, {
            headers: {
              'X-Requested-With': 'XMLHttpRequest'
            }
          })

          if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`)
          }

          if (proxyUrl.includes('allorigins.win')) {
            const data = await response.json()
            if (!data.contents) {
              throw new Error('No content received from allorigins proxy')
            }
            html = data.contents
          } else {
            html = await response.text()
          }

          if (html && html.includes('lighterpack')) {
            console.log(`Successfully fetched with proxy: ${proxyUrl}`)
            break
          } else {
            throw new Error('Invalid LighterPack content received')
          }
        } catch (error) {
          console.warn(`Proxy failed: ${proxyUrl}`, error)
          lastError = error
          continue
        }
      }

      if (!html) {
        throw new Error(`All CORS proxies failed. Last error: ${lastError instanceof Error ? lastError.message : 'Unknown error'}`)
      }

      // Parse the HTML content
      const result = parseLighterPackHtml(html)

      if (result.success) {
        const successMessage = result.metadata?.listName
          ? [`Successfully parsed "${result.metadata.listName}"`]
          : []
        onImportData(result.data, result.errors, successMessage, result.metadata)
      } else {
        onImportData([], result.errors)
      }
    } catch (error) {
      onImportData([], [`Failed to import from URL: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* URL Input */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="lighterpack-url">LighterPack URL</Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => window.open('https://lighterpack.com/r/q7l72y', '_blank')}
          >
            <ExternalLink className="h-3 w-3 mr-1" />
            View Example
          </Button>
        </div>
        <div className="flex gap-2">
          <Input
            id="lighterpack-url"
            type="url"
            placeholder="https://lighterpack.com/r/q7l72y"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            disabled={isProcessing}
            className="flex-1"
          />
          <Button
            onClick={handleUrlImport}
            disabled={!url.trim() || isProcessing}
          >
            {isProcessing ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-current mr-2" />
                Loading...
              </>
            ) : (
              'Import'
            )}
          </Button>
        </div>
        <div className="text-sm text-muted-foreground">
          Enter the share URL from your LighterPack list
        </div>
      </div>

      {/* Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">How to get your LighterPack URL:</div>
          <ol className="list-decimal list-inside space-y-1 text-sm">
            <li>Go to your LighterPack list</li>
            <li>Hover over the "Share" link and copy the list URL</li>
            <li>It should look like: <code className="bg-muted px-1 rounded">lighterpack.com/r/abc123</code></li>
            <li>Copy and paste the entire URL above</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* What Gets Imported */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">What gets imported:</div>
          <ul className="list-disc list-inside space-y-1 text-sm">
            <li>All gear items with names and descriptions</li>
            <li>Weights (preserved in original units - oz, lb, kg, or g)</li>
            <li>Categories (automatically mapped to BetterPack categories)</li>
            <li>Quantities, prices, and worn/consumable flags</li>
            <li>Duplicates are automatically detected and skipped</li>
          </ul>
        </AlertDescription>
      </Alert>
    </div>
  )
}

import { ReactNode } from 'react'
import { LucideIcon } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { cn } from '@/lib/utils'

interface StatTileProps {
  title: string
  value: string | number
  description?: string
  icon?: LucideIcon
  iconColor?: 'primary' | 'success' | 'warning' | 'info' | 'danger'
  onClick?: () => void
  className?: string
  children?: ReactNode
}

const iconColorClasses = {
  primary: 'bg-primary/10 text-primary',
  success: 'bg-success/10 text-success', 
  warning: 'bg-warning/10 text-warning',
  info: 'bg-info/10 text-info',
  danger: 'bg-destructive/10 text-destructive'
}

export function StatTile({ 
  title, 
  value, 
  description, 
  icon: Icon, 
  iconColor = 'primary',
  onClick,
  className,
  children
}: StatTileProps) {
  return (
    <Card 
      className={cn(
        "border-border/40 shadow-sm hover:shadow-md transition-all duration-150",
        onClick && "cursor-pointer active:scale-95",
        className
      )}
      onClick={onClick}
    >
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2 sm:pb-3">
        <CardTitle className="text-xs sm:text-sm font-medium text-muted-foreground">
          {title}
        </CardTitle>
        {Icon && (
          <div className={cn("p-1.5 sm:p-2 rounded-lg", iconColorClasses[iconColor])}>
            <Icon className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          </div>
        )}
      </CardHeader>
      <CardContent className="pb-3 sm:pb-6">
        <div className="text-2xl sm:text-3xl font-bold">{value}</div>
        {description && (
          <p className="text-xs text-muted-foreground mt-0.5 sm:mt-1">{description}</p>
        )}
        {children}
      </CardContent>
    </Card>
  )
}

